INSERT INTO `v1_6b8bcd1b764667f9784382a27f8c4d4fee8d479e68117c4972a20f4cd2404793` VALUES (13020015, 111031, "", "いかんいかん\n資材の山に埋もれて\nしまうところだった", 11, 10, "", "", 302, "", "");
INSERT INTO `v1_6b8bcd1b764667f9784382a27f8c4d4fee8d479e68117c4972a20f4cd2404793` VALUES (13020016, 0, "", "", 91, "", "", "", 302, "", "");
