INSERT INTO `v1_6b8bcd1b764667f9784382a27f8c4d4fee8d479e68117c4972a20f4cd2404793` VALUES (13020019, 111031, "", "だが怪我の功名、\n探していた部品を\n偶然にも発見できた", 11, 10, "", "", 302, "", "");
