INSERT INTO `v1_6b8bcd1b764667f9784382a27f8c4d4fee8d479e68117c4972a20f4cd2404793` VALUES (13020023, 111031, "", "ふむ…これは僥倖\nかくなる上は再び\n潜航してみるか…", 11, 10, "", "", 302, "", "");
INSERT INTO `v1_6b8bcd1b764667f9784382a27f8c4d4fee8d479e68117c4972a20f4cd2404793` VALUES (13020024, 0, "", "", 91, "", "", "", 302, "", "");
