INSERT INTO `v1_6b8bcd1b764667f9784382a27f8c4d4fee8d479e68117c4972a20f4cd2404793` VALUES (13020026, 111031, "", "存外意義あるものだ\n資材ダイビングとか\nいう新種の探索行は", 11, 10, "", "", 302, "", "");
INSERT INTO `v1_6b8bcd1b764667f9784382a27f8c4d4fee8d479e68117c4972a20f4cd2404793` VALUES (13020027, 0, "", 1, 91, "", "", "", 302, "", "");
INSERT INTO `v1_6b8bcd1b764667f9784382a27f8c4d4fee8d479e68117c4972a20f4cd2404793` VALUES (13020028, 111031, "", "まあ万一溺れたとて\n後輩たちの誰ぞが\nきっと気付くだろう", 11, 10, "", "", 302, "", "");
INSERT INTO `v1_6b8bcd1b764667f9784382a27f8c4d4fee8d479e68117c4972a20f4cd2404793` VALUES (13020029, 0, "", 1, 91, "", "", "", 302, "", "");
